/** Embed the CI catalog in the Toolbox package for offline starters. */
import { readFileSync, writeFileSync } from "node:fs";
import process from "node:process";
import { URL } from "node:url";

const paths = ["ci/verify.sh", "ci/github-actions/verify.yml", "ci/gitlab/verify.yml"];
const target = new URL("../../packages/foundation/toolbox/src/starter-project/starter-ci-workflow.ts", import.meta.url);
const rendered = [
  "// Generated by scripts/build/sync-starter-workflow.mjs from the CI catalog.",
  "// prettier-ignore",
  "export const starterCiFiles = [",
  ...paths.flatMap((path) => {
    const file = new URL(`../../${path}`, import.meta.url);
    const lines = readFileSync(file, "utf8").trimEnd().split(/\r?\n/u);
    return [
      "  {",
      `    path: ${JSON.stringify(path)},`,
      "    content: [",
      ...lines.map((line) => `      ${JSON.stringify(line)},`),
      '      "",',
      '    ].join("\\n"),',
      "  },",
    ];
  }),
  "];",
  "",
].join("\n");

if (process.argv[2] === "--check") {
  if (readFileSync(target, "utf8") !== rendered) {
    process.stderr.write("Starter CI files are out of date. Run node scripts/build/sync-starter-workflow.mjs.\n");
    process.exitCode = 1;
  }
} else {
  writeFileSync(target, rendered);
}
